const net = require('net');
const crypto = require('crypto');

class ConnectionPool {
  constructor(maxSize = 50) {
    this.pool = new Map();
    this.maxSize = maxSize;
    this.refCounts = new Map();
    this.cleanupQueue = [];
    this.gcInterval = setInterval(() => this._gc(), 5000);
  }

  acquire(clientId) {
    if (this.pool.has(clientId)) {
      const conn = this.pool.get(clientId);
      this.refCounts.set(clientId, (this.refCounts.get(clientId) || 0) + 1);
      return conn;
    }
    return null;
  }

  register(clientId, socket) {
    if (this.pool.size >= this.maxSize) {
      this._evictOldest();
    }
    this.pool.set(clientId, { socket, createdAt: Date.now(), state: 'active' });
    this.refCounts.set(clientId, 1);
  }

  release(clientId) {
    const count = this.refCounts.get(clientId) || 0;
    if (count <= 1) {
      this.refCounts.set(clientId, 0);
      this._scheduleCleanup(clientId);
    } else {
      this.refCounts.set(clientId, count - 1);
    }
  }

  _scheduleCleanup(clientId) {
    this.cleanupQueue.push({ clientId, scheduledAt: Date.now() });
  }

  _gc() {
    const now = Date.now();
    const pending = [];
    for (const item of this.cleanupQueue) {
      if (now - item.scheduledAt > 2000) {
        this._destroy(item.clientId);
      } else {
        pending.push(item);
      }
    }
    this.cleanupQueue = pending;
  }

  _destroy(clientId) {
    const conn = this.pool.get(clientId);
    if (conn) {
      conn.state = 'destroyed';
      if (conn.socket && !conn.socket.destroyed) {
        conn.socket.destroy();
      }
      this.pool.delete(clientId);
      this.refCounts.delete(clientId);
    }
  }

  _evictOldest() {
    let oldest = null;
    let oldestId = null;
    for (const [id, conn] of this.pool) {
      if (!oldest || conn.createdAt < oldest.createdAt) {
        oldest = conn;
        oldestId = id;
      }
    }
    if (oldestId) this._destroy(oldestId);
  }
}

class ChatRoom {
  constructor(name) {
    this.name = name;
    this.members = new Set();
    this.messageLog = [];
  }

  join(clientId) { this.members.add(clientId); }
  leave(clientId) { this.members.delete(clientId); }
  getMembers() { return [...this.members]; }
}

class ChatServer {
  constructor(port) {
    this.pool = new ConnectionPool(100);
    this.rooms = new Map();
    this.clientRooms = new Map();
    this.server = net.createServer((socket) => this._onConnection(socket));
    this.port = port;
  }

  start() {
    this.server.listen(this.port, () => {
      console.log(`Chat server on port ${this.port}`);
    });
  }

  _onConnection(socket) {
    const clientId = crypto.randomBytes(16).toString('hex');
    this.pool.register(clientId, socket);
    this.clientRooms.set(clientId, new Set());

    socket.on('data', (data) => this._handleMessage(clientId, data));
    socket.on('close', () => this._handleDisconnect(clientId));
    socket.on('error', () => this._handleDisconnect(clientId));
    socket.write(JSON.stringify({ type: 'welcome', clientId }) + '\n');
  }

  _handleMessage(clientId, data) {
    try {
      const msg = JSON.parse(data.toString().trim());
      switch (msg.type) {
        case 'join': this._joinRoom(clientId, msg.room); break;
        case 'leave': this._leaveRoom(clientId, msg.room); break;
        case 'msg': this._broadcast(clientId, msg.room, msg.text); break;
        case 'disconnect': this._handleDisconnect(clientId); break;
      }
    } catch (e) { /* malformed message */ }
  }

  _joinRoom(clientId, roomName) {
    if (!this.rooms.has(roomName)) {
      this.rooms.set(roomName, new ChatRoom(roomName));
    }
    this.rooms.get(roomName).join(clientId);
    this.clientRooms.get(clientId)?.add(roomName);
    this.pool.acquire(clientId);
  }

  _leaveRoom(clientId, roomName) {
    const room = this.rooms.get(roomName);
    if (room) {
      room.leave(clientId);
      this.clientRooms.get(clientId)?.delete(roomName);
      this.pool.release(clientId);
    }
  }

  _broadcast(clientId, roomName, text) {
    const room = this.rooms.get(roomName);
    if (!room) return;
    const payload = JSON.stringify({ type: 'msg', from: clientId, room: roomName, text }) + '\n';
    for (const memberId of room.getMembers()) {
      const conn = this.pool.acquire(memberId);
      if (conn && conn.state === 'active' && conn.socket && !conn.socket.destroyed) {
        conn.socket.write(payload);
      }
      this.pool.release(memberId);
    }
  }

  _handleDisconnect(clientId) {
    const rooms = this.clientRooms.get(clientId);
    if (rooms) {
      for (const roomName of rooms) {
        this.rooms.get(roomName)?.leave(clientId);
        this.pool.release(clientId);
      }
    }
    this.pool.release(clientId);
    this.clientRooms.delete(clientId);
  }
}

